float calibrationTemperatureT1 = 0.0; // Final temperature reading
float calibrationHumidityR0 = 0.0; // Initial humidity reading
float calibrationHumidityR1 = 0.0; // Final humidity reading

void setup() {
  Serial.begin(9600);
  dht.begin();
}

