  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Write the values to the serial monitor
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.print("°C, ");
  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println("%");

  // Perform the calibration step (only needed during calibration)
  if (temperature > calibrationTemperatureT0) {
    calibrationTemperatureT0 = temperature;
  }
  if (humidity > calibrationHumidityR0) {
    calibrationHumidityR0 = humidity;
  }
  if (temperature < calibrationTemperatureT1) {
    calibrationTemperatureT1 = temperature;
  }
  if (humidity < calibrationHumidityR1) {
    calibrationHumidityR1 = humidity;
  }

  // Check if the calibration is complete
  if (temperature >= calibrationTemperatureT1 && humidity <= calibrationHumidityR1) {
