const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

const G = 9.81; // gravitational constant in m/s^2
const L = 100; // length of the pendulum in pixels
const M = 1; // mass of the pendulum in kg (just a placeholder, not actual mass)
const T = 60; // time step in seconds

let theta = 0; // initial angle in radians
let omega = 0; // initial angular velocity in radians per second
let time = 0; // current time in seconds
let released = false; // has the pendulum been released?

// Function to convert degrees to radians
function degToRad(deg) {
    return deg * Math.PI / 180;
}

// Function to update the pendulum's position and velocity
function update() {
    if (!released) {
        return; // pendulum hasn't been released yet
    }

    // Calculate the acceleration due to gravity
    let a = -G / L * Math.sin(theta);

    // Update the angular velocity
    omega += a * T;

    // Update the angle
    theta += omega * T;

    // Ensure the pendulum doesn't swing too far
    if (Math.abs(theta) > Math.PI / 2) {
        theta = Math.sign(theta) * Math.PI / 2;
        omega = 0; // bring the pendulum to a stop
    }

    // Check if the pendulum has stopped swinging
    if (Math.abs(omega) < 0.01) {
        released = false; // pendulum has stopped, release
    }

    // Update the time
    time += T;

    // Draw the pendulum
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2, L, canvas.width / 2, canvas.height / 2, theta, true);
    ctx.stroke();
}

// Function to release the pendulum
function release() {
    released = true;
    omega = degToRad(document.getElementById('angle').value); // set initial angular velocity
}

// Main loop
setInterval(() => {
    update();
}, T * 1000); // update every T seconds

// Add event listener to the release button
document.getElementById('release').addEventListener('click', release);
